DO $$
DECLARE
  rec RECORD;
  cur_status VARCHAR(20);
  cur_reserved_by INT;
  cur_reserved_at TIMESTAMP;
BEGIN
  FOR rec IN SELECT * FROM match_requests ORDER BY request_id LOOP
    SELECT status, reserved_by, reserved_at INTO cur_status, cur_reserved_by, cur_reserved_at
    FROM match_slots WHERE slot_id = rec.slot_id;

    IF rec.request_type = 1 AND cur_status = 'available' THEN
      UPDATE match_slots
      SET status = 'reserved',
          reserved_by = rec.user_id,
          reserved_at = rec.requested_at
      WHERE slot_id = rec.slot_id;
    ELSIF rec.request_type = 2 AND cur_status = 'reserved' AND cur_reserved_by = rec.user_id THEN
      UPDATE match_slots
      SET status = 'confirmed'
      WHERE slot_id = rec.slot_id;
    ELSIF rec.request_type = 3 AND cur_status = 'reserved' AND cur_reserved_by = rec.user_id THEN
      UPDATE match_slots
      SET status = 'available',
          reserved_by = NULL,
          reserved_at = NULL
      WHERE slot_id = rec.slot_id;
    END IF;
  END LOOP;
END $$;

SELECT * FROM match_slots ORDER BY slot_id;
